import re as _zq_re


def _zq_class(p, i):
    # p[i] == '['; return (regex, next index) or None when unclosed
    j = i + 1
    neg = False
    if j < len(p) and p[j] in '!^':
        neg = True
        j += 1
    out = []
    first = True
    while j < len(p):
        c = p[j]
        if c == ']' and not first:
            body = ''.join(out)
            return ('[^/' + body + ']' if neg else '(?!/)[' + body + ']'), j + 1
        first = False
        if c == '[' and p.startswith('[:', j):
            k = p.find(':]', j + 2)
            if k < 0:
                return None
            name = p[j + 2:k]
            table = {'alpha': 'a-zA-Z', 'digit': '0-9', 'alnum': 'a-zA-Z0-9',
                     'upper': 'A-Z', 'lower': 'a-z', 'space': ' \\t\\n\\r\\f\\v',
                     'xdigit': '0-9a-fA-F', 'punct': _zq_re.escape('!"#$%&\'()*+,-./:;<=>?@[\\]^_`{|}~')}
            if name not in table:
                return None
            out.append(table[name])
            j = k + 2
            continue
        if c == '\\' and j + 1 < len(p):
            out.append(_zq_re.escape(p[j + 1]))
            j += 2
            continue
        if j + 2 < len(p) and p[j + 1] == '-' and p[j + 2] != ']':
            hi = p[j + 2]
            if hi == '\\' and j + 3 < len(p):
                hi = p[j + 3]
                j += 1
            out.append(_zq_re.escape(c) + '-' + _zq_re.escape(hi))
            j += 3
            continue
        out.append(_zq_re.escape(c))
        j += 1
    return None


def _zq_glob(p):
    # git wildmatch with WM_PATHNAME, as a regular expression
    out = []
    i = 0
    n = len(p)
    while i < n:
        c = p[i]
        if c == '*':
            j = i
            while j < n and p[j] == '*':
                j += 1
            double = j - i >= 2 and (i == 0 or p[i - 1] == '/')
            if double and j == n:
                out.append('.*')
            elif double and p[j] == '/':
                out.append('(?:.*/)?')
                j += 1
            else:
                out.append('[^/]*')
            i = j
        elif c == '?':
            out.append('[^/]')
            i += 1
        elif c == '[':
            got = _zq_class(p, i)
            if got is None:
                out.append(_zq_re.escape('['))
                i += 1
            else:
                out.append(got[0])
                i = got[1]
        elif c == '\\':
            if i + 1 < n:
                out.append(_zq_re.escape(p[i + 1]))
                i += 2
            else:
                return None
        else:
            out.append(_zq_re.escape(c))
            i += 1
    return _zq_re.compile('(?s)' + ''.join(out) + r'\Z')


def _zq_rules(text):
    rules = []
    for line in str(text).split('\n'):
        line = line.rstrip('\r')
        k = len(line)
        while k > 0 and line[k - 1] == ' ' and not (k > 1 and line[k - 2] == '\\'):
            k -= 1
        line = line[:k]
        if not line or line.startswith('#'):
            continue
        neg = line.startswith('!')
        if neg:
            line = line[1:]
        must_dir = line.endswith('/')
        if must_dir:
            line = line[:-1]
        if not line:
            continue
        basename = '/' not in line
        if line.startswith('/'):
            line = line[1:]
        rx = _zq_glob(line)
        if rx is not None:
            rules.append((neg, must_dir, basename, rx))
    return rules


def _zq_excluded(rules, path, is_dir):
    for neg, must_dir, basename, rx in reversed(rules):
        if must_dir and not is_dir:
            continue
        target = path.rsplit('/', 1)[-1] if basename else path
        if rx.match(target):
            return not neg
    return False


def _zq_ignored(path, text):
    rules = _zq_rules(text)
    parts = path.strip('/').split('/')
    for k in range(1, len(parts)):
        if _zq_excluded(rules, '/'.join(parts[:k]), True):
            return True
    return _zq_excluded(rules, '/'.join(parts), False)


def ignored(path):
    return _zq_ignored(path, globals().get('GITIGNORE', ''))

